\label{thmA}
   Suppose 
  $\mathcal{E}$ is a twist 
  over a locally compact, Hausdorff, {\'e}tale\ groupoid~$G$, and 
  $S$
  is an open subgroupoid of $G$. 
  Then the following statements  are equivalent.
  \begin{enumerate}[label=\textup{(\roman*)}]

    \item $i(\ensuremath{C^{*}}_{r}(S;\mathcal{E}_{S}))$ is a Cartan subalgebra of $\ensuremath{C^{*}}_{r}(G;\mathcal{E})$ whose normalizer contains every $h\in C_{c}(G;\mathcal{E})$ with  $\pi(\operatorname{supp}^{\circ}(h))$ a bisection.

    \item  $S$ is maximal among open subgroupoids of $\operatorname{int}_{G}\left({G'}\right)$ for which
      $\mathcal{E}_{S}$ is abelian, $S$ is closed and normal in $G$, and the set
      \begin{equation}
        \bigl\{e\in{\mathcal{E}'} :  1 < |\{\sigma^{-1} e\sigma:\sigma \in \mathcal{E}_{S}\}|= |\{s^{-1} \pi(e)s:s \in S\}|<\infty\bigr\}
        \end{equation}
        has empty interior in $\mathcal{E}$.
  \end{enumerate}

\label{lem:j-map commutes} Let $\mathcal{E}$ be a twist over an {\'e}tale\
  groupoid $G$.  If $S$ is an open subgroupoid of~$G$ and
  we let
  $\mathcal{E}_{S}=\pi^{-1} (S)$, then
  \begin{equation}
    \label{eq:8}
    \begin{tikzcd}
      S^{(0)}\times \mathbf{T}\arrow[r,"\iota",hook] &\mathcal{E}_{S} \arrow[r,"\pi",two
      heads]& S
    \end{tikzcd}
  \end{equation}
  is a twist over $S$ and ``extension by zero'' from
  $C_{c}(S;\mathcal{E}_{S})\to C_{c}(G;\mathcal{E} )$ extends to an inclusion
  $i\colon \ensuremath{C^{*}}_{r}(S;\mathcal{E}_{S})\to \ensuremath{C^{*}}_{r}(G;\mathcal{E})$.  Furthermore, the
  diagram
  \begin{equation}
    \label{eq:9}
    \begin{tikzcd}
      C_{c}(S;\mathcal{E}_{S}) \arrow[r,hook] \arrow[d,hook,"i"] &
      \ensuremath{C^{*}}_{r}(S;\mathcal{E}_{S}) \arrow[r,,"j_{S}"] \arrow[d,"i",hook] &
      C_{0}(S;\mathcal{E}_{S}) \arrow[d,hook,"i"] \\
      C_{c}(G;\mathcal{E}) \arrow[r,hook] & \ensuremath{C^{*}}_{r}(G;\mathcal{E}) \arrow[r,"j_{G}"] &
      C_{0}(G;\mathcal{E})
    \end{tikzcd}
  \end{equation}
  commutes.

\label{thm:May17}
   Suppose 
  $\mathcal{E}$ is a twist 
  over a locally compact, Hausdorff, {\'e}tale\ groupoid~$G$, and $S$ is an open subgroupoid of $G$. Let $B=i(\ensuremath{C^{*}}_{r}(S;\mathcal{E}_{S}))$ and $A=\ensuremath{C^{*}}_{r}(G;\mathcal{E})$. Then the following statements  are equivalent.
  \begin{enumerate}[label=\textup{(\roman*)}]

    \item\label{it:thm:May17:B:subset} $B$ is a Cartan subalgebra of $A$ for which
    \begin{equation}
        \{\,
        h\in C_{c}(G;\mathcal{E}):
        \pi(\operatorname{supp}^{\circ}(h)) \text{ is a bisection}
        \,\} \subset N(B).
    \end{equation}

    \item\label{it:thm:May17:B:cap} $B$ is a Cartan subalgebra of $A$ for which the set
    \begin{equation}\label{eq:thm:May17:B cap} 
       \{\,
        a\in A:
        \pi(\operatorname{supp}^{\circ}(j_{G}(a))) \text{ is a bisection}
        \,\} 
        \cap  N(B)
    \end{equation}
    generates $A$.

    \item\label{it:thm:May17:S:Omega} We have 
      \begin{gather}  
      G^{(0)}\subset S
      \text{ and }
      \operatorname{int}_{\mathcal{E}}\left(\Omega_{S}^{-1}(\{\,1\,\})\right)=\mathcal{E}_{S},
      \label{eq:thm:May17:Int Omega=1}
      \tag{ 
      \textsf{max}}
      \\
        \label{eq:thm:May17:icc}
        \operatorname{int}_{\mathcal{E}}\left(\Omega_{S}^{-1} (\mathbf{Z}_{>1})\right)=\emptyset
        \tag{ 
        \textsf{ricc}}
        ,
    \end{gather}
      and $S$ is closed and normal in $G$.
      \item\label{it:thm:May17:S:Omega+max} $S$ is maximal among open subgroupoids of $\operatorname{int}_{G}\left({G'}\right)$ for which
      $\mathcal{E}_{S}$ is abelian,  $S$ satisfies Condition~\eqref{eq:thm:May17:icc}, and $S$ is closed and normal in $G$.
  \end{enumerate}

If the twist $\mathcal{E}$ is induced by a $2$-cocycle $c$ (see Example~\ref{ex:twist given by $2$-cocycle}), one could of course translate the equivalent conditions of
    Theorem~\ref{thm:May17}
    into conditions on $c$. As we have not found these conditions to be very enlightening, we refrain from doing so here.

\label{lem:effectiveness}
       Suppose $G$ is a locally compact, Hausdorff, {\'e}tale\ groupoid. The following are equivalent.
       \begin{enumerate}[label=\textup{(\roman*)}]
           \item $G$ is effective;
           \item $G$ contains no non-trivial open abelian subgroupoid.
       \end{enumerate}

\label{rmk:cocycle symmetric}
    Applying Corollary~\ref{cor:S max in terms of Omega}\ref{item:cor:S max implies}
    to $2$-cocycles, the only change is that the phrase ``\emph{\ldots for which $\mathcal{E}_{S}$ is abelian}'' becomes ``\emph{\ldots
    which are abelian and
    for which $c$ is symmetric}''.

We recover \cite{ABOCLMR:2023:Local_Bisection-pp}*{Theorem 3.1, $(1)\iff(2)$} and, in particular, \cite{ren:irms08}*{Theorem 5.2}: for a locally compact, Hausdorff, {\'e}tale\ groupoid $G$, effectiveness is equivalent to $i(C_0(G^{(0)}))$ being a Cartan subalgebra of $\ensuremath{C^{*}}_r(G;\mathcal{E})$ for any twist $\mathcal{E}$. 

To see this, fix a twist $\mathcal{E}$ and an element $e\in\operatorname{int}_{\mathcal{E}}\left({\mathcal{E}'}\right)$. Since $ \mathcal{E}_{G^{(0)}}=\pi^{-1}(G^{(0)})=\iota(G^{(0)}\times\mathbf{T})$ and since $\iota$ is central, we have
\[
    \operatorname{Ad}_{\mathcal{E},G^{(0)}}(e)
    =
    \{\,
        \tau^{-1} e \tau 
        :\tau\in \mathcal{E}_{G^{(0)}}
    \,\}
    =
    \{\,e\,\},
    \text{ and }
    \operatorname{Ad}_{\mathcal{E},G^{(0)}}(\pi(e))=\{\,\pi(e)\,\},
\]
where we have added the extra subscript-$\mathcal{E}$ to emphasize the dependence of the set on the twist. This means that any element $e\in\operatorname{int}_{\mathcal{E}}\left({\mathcal{E}'}\right)$ satisfies $\Omega_{\mathcal{E},G^{(0)}}(e)=1$. Thus,
\begin{equation}\label{eq:effective case}
    \operatorname{int}_{\mathcal{E}}\left(\Omega_{\mathcal{E},G^{(0)}}^{-1}(\{\,1\,\})\right)
    = \operatorname{int}_{\mathcal{E}}\left({\mathcal{E}'}\right)
    \quad\text{and}\quad
    \operatorname{int}_{\mathcal{E}}\left(\Omega_{\mathcal{E},G^{(0)}}^{-1}(\mathbf{Z}_{>1})\right)
    = \emptyset.
\end{equation}
Since $G^{(0)}$ is always closed and a normal subgroupoid of $G$ (it is just a space), and since $G^{(0)}$ is also open by the {\'e}tale\ assumption, we can use
Corollary~\ref{cor:Breg} (in tandem with Corollary~\ref{cor:regular if normal})
to get the following chain of equivalences:
\begin{align*}
    G\text{ effective }
    &\overset{\text{def}}{\iff} 
    G^{(0)}=\operatorname{int}_{G}\left({G'}\right)
    \overset{\text{L.~\ref{lem:int is sbgpd}}}{\iff}
    \text{For any }\mathcal{E}, \mathcal{E}_{G^{(0)}} = \operatorname{int}_{\mathcal{E}}\left({\mathcal{E}'}\right)
    \\&
    \overset{\eqref{eq:effective case}}{\iff} 
    \text{For any }\mathcal{E}, 
    \mathcal{E}_{G^{(0)}}=
    \operatorname{int}_{\mathcal{E}}\left(\Omega_{\mathcal{E},G^{(0)}}^{-1}(\{\,1\,\})\right)
    \text{ and }    \operatorname{int}_{\mathcal{E}}\left(\Omega_{\mathcal{E},G^{(0)}}^{-1}(\mathbf{Z}_{>1})\right)
    = \emptyset
    \\
    &\overset{
    \ref{cor:Breg}
    }{\iff}
    \text{For any }\mathcal{E}, 
    i(C_0(G^{(0)}))\text{ is a Cartan subalgebra of }\ensuremath{C^{*}}_r(G;\mathcal{E}).
\end{align*}

\label{cor:formerly thm:main}
  Let 
  $\mathcal{E}$ be a twist 
  over a locally compact, Hausdorff, {\'e}tale\ groupoid~$G$.  Assume that $S$ is maximal among open subgroupoids of
  $\operatorname{int}_{G}\left({G'}\right)$ for which $\mathcal{E}_{S}$ is abelian, and that $S$ is
  closed and normal in $G$. If we have
\begin{equation}   
    \label{eq:icc}
        \forall u\in G^{(0)}, g\in G(u)\cap \operatorname{int}_{G}\left({G'}\right):
        |\{\,t^{-1} g t: t\in S(u)\,\}|\in \{\,1,\infty\,\},
\end{equation} 
  then
  $i(\ensuremath{C^{*}}_{r}(S;\mathcal{E}_{S}))$ is a Cartan subalgebra of $\ensuremath{C^{*}}_{r}(G;\mathcal{E})$.

\label{rmk:icc vs immcentr}
A subgroupoid $S$ of $G$ is called \emph{immediately centralizing} in ${G'}$ if the following holds.
\begin{align}\label{eq:immcentr}
    \begin{split}
        &\forall u\in G^{(0)}, g\in G(u), k\in\mathbf{Z}:
        \\
        &\qquad\bigl[\forall s \in S(u), \exists 1 \leq j \leq k, gs^j = s^jg\bigr] \implies \bigl[\forall s \in S(u), gs=sg\bigr].
    \end{split}
    \end{align}
In \cite{DGNRW:Cartan}*{Theorem 3.1} and \cite{BG:2023:Gamma-Cartan-pp}*{Proposition 3.4},  conditions on a subgroupoid $S$ of $G$ are listed that imply that, in the $2$-cocycle twisted $\ensuremath{C^{*}}$-algebra $\ensuremath{C^{*}}_{r}(G,c)$, the subalgebra  $i(\ensuremath{C^{*}}_r(S,c|_{S^{(2)}}))$ is a Cartan. Like in our
Theorem~\ref{thm:May17}\ref{it:thm:May17:S:Omega+max},
$S$ was assumed to be clopen, normal, and maximal; the assumption that $S$ be immediately centralizing was then invoked to prove maximality of the subalgebra.
Let us quickly explain that Condition~\eqref{eq:immcentr} implies Condition~\eqref{eq:icc} in the last corollary, which proves that Corollary~\ref{cor:formerly thm:main} implies \cite{DGNRW:Cartan}*{Theorem 3.1} and \cite{BG:2023:Gamma-Cartan-pp}*{Proposition 3.4}.


Take $g\in G(u)\cap \operatorname{int}_{G}\left({G'}\right)$  such that $|\{\,t^{-1} g t: t\in S(u)\,\}|>1$, 
 so there exists $t\in S(u)$ with $gt\neq tg$. By Condition~\eqref{eq:immcentr} applied to any $k\geq 1$, this means there exists $s\in S(u)$ such that for all $1\leq j\leq k$ we have $gs^j\neq s^jg$; in particular, the set $\{\,s^{-j}gs^{j}: 1\leq j\leq k\,\}$ has $k$ many distinct elements. As $k$ was arbitrary, this shows that $\{t^{-1} g t: t\in S(u)\}$ must be infinite, or in other words $|\{\,t^{-1} g t: t\in S(u)\,\}|=\infty$, as claimed.

    In Example~\ref{ex:immcentr is bad}, we show that the converse implication is false: There are pairs of groupoids $S\leq G$ that satisfy~\eqref{eq:icc} but not~\eqref{eq:immcentr}. This shows that, even in the case of twists induced from $2$-cocycles, Corollary~\ref{cor:formerly thm:main} is stronger than its predecessors \cite{DGNRW:Cartan}*{Theorem 3.1} and \cite{BG:2023:Gamma-Cartan-pp}*{Proposition 3.4}.

\label{cor:main-thm for trivial twist}
  Let $G$ be a locally compact, Hausdorff, {\'e}tale\ groupoid.
For an open subgroupoid $S$ of $G$, the following are equivalent.
  \begin{enumerate}[label=\textup{(\roman*)}]

    \item\label{it:main-thm for trivial twist:B} $i(\ensuremath{C^{*}}_{r}(S))$ is a Cartan subalgebra of $\ensuremath{C^{*}}_{r}(G)$,
    and the set
    \begin{equation} 
       \{\,
        a\in \ensuremath{C^{*}}_{r}(G):
        \operatorname{supp}^{\circ}(j_{G}(a)) \text{ is a bisection}
        \,\} 
        \cap  N(i(\ensuremath{C^{*}}_{r}(S)))
    \end{equation}
    generates $\ensuremath{C^{*}}_{r}(G)$.
      \item\label{it:main-thm for trivial twist:S} $S$ is maximal among abelian open subgroupoids of
  $\operatorname{int}_{G}\left({G'}\right)$, $S$ is closed and normal in $G$, and the set
  \[
    \Bigl\{
    g\in {G'}: 1< |\{\,t^{-1} g t:t\in S\,\}|<\infty
    \Bigr\}
  \]
  has empty interior.

  \end{enumerate}

\label{rmk:where does open go}
     The implication \ref{it:main-thm for trivial twist:S}$\implies$\ref{it:main-thm for trivial twist:B} of  Corollary~\ref{cor:main-thm for trivial twist} is a stronger result than applying the main theorem of \cite{DGNRW:Cartan}*{Theorem 3.1}  to a trivial $2$-cocycle. In both theorems, $S$ is assumed to be open, but in \cite{DGNRW:Cartan}*{Theorem 3.1}, the maximality assumption is with respect to all subgroupoids of ${G'}$ (not necessarily open ones and not necessarily in the interior of ${G'}$). See also
    the proof of \cite{BG:2023:Gamma-Cartan-pp}*{Proposition 3.4} for a discussion. In particular, Corollary~\ref{cor:main-thm for trivial twist} recovers a result in \cite{BNRSW:Cartan} about untwisted groupoid $\ensuremath{C^{*}}$-algebras that is not a corollary of \cite{DGNRW:Cartan}*{Theorem 3.1}; see Corollary~\ref{cor:BNRWS}.
